update_rule.pseudocode:
for each day d:
  assign persons to contexts (home, work/school, public) with probability mobility_rate
  enforce location capacity; if overflow, reassign to nearest alternative public location
  for each location L:
    n_contacts = Poisson(contact_rate_type(L.type) * L.contact_rate_modifier)
    generate contact pairs using configuration model constrained by occupancy
    for each contact pair (i,j):
      emit contact event with location=L.id, ventilation=L.ventilation_level
  output contacts.daily_list and ventilation_per_contact arrays

if day % monitoring_interval_days == 0:
  if current_incidence_per_100k >= case_threshold_on:
    mandate_status = True
  elif current_incidence_per_100k <= case_threshold_off:
    mandate_status = False
  enforcement_strength = base_enforcement_strength * policy_effectiveness
  campaign_intensity_signal = campaign_intensity * (1 if mandate_status else 0.5)
  subsidy_per_mask_out = subsidy_per_mask
  fine_amount_out = fine_amount
emit outputs each day (holding last values when not updated)

if disease_module_enabled:
  new_inf = 0
  for each contact (i,j,location_type,vent_level):
    if (i infectious and j susceptible) or (j infectious and i susceptible):
      mask_factor = (1 - mask_efficacy_outward if infectious wears) * (1 - mask_efficacy_inward if susceptible wears)
      vent_factor = 1 - ventilation_effect_public * vent_level
      p_trans = base_transmission_rate * mask_factor * vent_factor
      if Bernoulli(p_trans):
        infect susceptible
        new_inf += 1
  prevalence = update with recoveries (fixed infectious period, e.g., 7 days), plus imported cases
  Re = moving_average(new_inf / prev_infectious, smoothing_window_for_Re)
  emit daily_new_infections, prevalence, Re
else:
  emit zeros and keep prevalence constant
